void hexdump(const void *data, size_t size) {
    const uint8_t *byte_data = (const uint8_t *)data; // 将数据强制转换为字节数组
    size_t i;
    for (i = 0; i < size; i++) {
        // 按16字节一行显示
        if (i % 16 == 0) {
        	rt_kprintf("%08x  ", (unsigned int)i); // 打印偏移地址
        }

        rt_kprintf("%02x ", byte_data[i]); // 打印十六进制数据

        // 每8字节后额外加一个空格
        if ((i + 1) % 8 == 0) {
        	rt_kprintf(" ");
        }

        // 每16字节后换行
        if ((i + 1) % 16 == 0) {
        	rt_kprintf("\n");
        }
    }

    // 如果最后一行不满16字节，补充换行
    if (i % 16 != 0) {
    	rt_kprintf("\n");
    }
}

// 手动实现的 expf 函数（使用 float 类型）
float my_expf(float x)
{
	if(x>4) return 1000;//54.598;
	if(x<-4) return 0.0001;//0.0183;
    float sum = 1.0f;  // e^x 的初始值为 1（对应 0 阶项）
    float term = 1.0f; // 当前项的值，初始值为 1
    int n = 1;
    // 累加 20 项（精度可以根据需要调整）
    for (int i = 1; i <= 20; i++)
    {
        term *= x / n;  // 计算当前项的值
        sum += term;    // 将当前项加入总和
        n++;
    }
    return sum;
}
void my_softmax(struct FloatTensor *result)
{
    float a1 = 0;
    float a2 = 0;
    float temp1 = 0;
    float temp2 = 0;
    for (int i = 0; i < result->height * result->width * result->channel / 17; i++)
    {
        a1 = result->data_location[i * 17 + 14];
        a2 = result->data_location[i * 17 + 15];

        if(a1 > a2){
            a2 = a2 - a1;
            a1 = 0;
        }
        else{
            a1 = a1 - a2;
            a2 = 0;
        }
        temp1 = my_expf(a1);
        temp2 = my_expf(a2);
        result->data_location[i * 17 + 14] = temp1 / (temp1 + temp2);
        result->data_location[i * 17 + 15] = temp2 / (temp1 + temp2);

    }
}

//======================
void get_priorbox(float *priorbox, int prior, int priorlen, int h_i, int w_j, int c_k, int image_w, int image_h)
{
    //int min_size[12] = {10, 16, 24,    32, 48,0,    64, 96,0,  128, 192, 256};
    // int steps[4] = { 8, 16, 32, 64 };
    int min_size[12] = {5, 8, 12, 16, 24, 0, 32, 48, 0,  64, 96, 128};
    int steps[4] = { 4, 8, 16, 32 };
    priorbox[2] = 2 * (float)min_size[3 * prior + c_k] / (float)(image_w);
    priorbox[3] = 2 * (float)min_size[3 * prior + c_k] / (float)(image_h);
    priorbox[0] = 2 * ((float)w_j + (float)0.5) * steps[prior] / (image_w);
    priorbox[1] = 2 * ((float)h_i + (float)0.5) * steps[prior] / (image_h);
}

float overlap(FaceRect  *face1, FaceRect  *face2)
{
    if (face1->x1 > face2->x2)
        return 0;
    if (face1->y1 > face2->y2)
        return 0;
    if (face1->x2 < face2->x1)
        return 0;
    if (face1->y2 < face2->y1)
        return 0;
    int colInt = abs(MIN(face1->x2, face2->x2) - MAX(face1->x1, face2->x1));
    int rowInt = abs(MIN(face1->y2, face2->y2) - MAX(face1->y1, face2->y1));
    float overlap_area = (float)colInt * (float)rowInt;
    int area1 = (face1->x2 - face1->x1) * (face1->y2 - face1->y1);
    int area2 = (face2->x2 - face2->x1) * (face2->y2 - face2->y1);
    return overlap_area / (float)(area1 + area2 - overlap_area);
}

static int select_top_k(const FaceRect* faces,
                        int face_count,
                        int* top_idx,
                        int k)
{
    int top_count = 0;

    for (int i = 0; i < face_count; i++) {
        float score = faces[i].score;

        int insert_pos = top_count;

        // 找插入位置
        for (int j = 0; j < top_count; j++) {
            if (score > faces[top_idx[j]].score) {
                insert_pos = j;
                break;
            }
        }

        if (insert_pos < k) {
            // 向后移动
            int end = (top_count < k) ? top_count : (k - 1);
            for (int j = end; j > insert_pos; j--) {
                top_idx[j] = top_idx[j - 1];
            }

            top_idx[insert_pos] = i;

            if (top_count < k)
                top_count++;
        }
    }

    return top_count;
}


int nms_top10(const FaceRect* faces,
              FaceRect* faces_result,
              int face_count,
              float threshold)
{
    rt_kprintf("[NMS_TOP10] Input: face_count=%d, threshold=%s\n", 
               face_count, float_to_string_simple(threshold));
    
    if (face_count <= 0)
        return 0;

    int top_idx[10];
    int top_count = select_top_k(faces, face_count, top_idx, 10);

    int suppressed[10];
    for (int i = 0; i < top_count; i++) {
        suppressed[i] = 0;
    }

    int result_count = 0;

    // NMS on Top-K
    for (int i = 0; i < top_count; i++) {
        if (suppressed[i])
            continue;

        faces_result[result_count++] = faces[top_idx[i]];

        for (int j = i + 1; j < top_count; j++) {
            if (suppressed[j])
                continue;

            if (overlap(&faces[top_idx[i]],
                        &faces[top_idx[j]]) > threshold) {
                suppressed[j] = 1;
            }
        }
        if (result_count == 3)break;
    }

    rt_kprintf("[NMS_TOP10] Output: result_count=%d\n", result_count);
    for (int i = 0; i < result_count; i++) {
        rt_kprintf("[NMS_TOP10] faces_result[%d]: box=(%d,%d,%d,%d) score=%s\n",
                   i, faces_result[i].x1, faces_result[i].y1, 
                   faces_result[i].x2, faces_result[i].y2,
                   float_to_string_simple(faces_result[i].score));
    }

    return result_count;
}

int nms(FaceRect* faces, FaceRect* faces_result, int face_count, float threshold) {
    if (face_count <= 0) return 0;

    int suppressed[face_count];
    for (int i = 0; i < face_count; i++) {
        suppressed[i] = 0;
    }

    int result_count = 0;
    for (int i = 0; i < face_count; i++) {
        if (suppressed[i] > 0) continue;

        faces_result[result_count++] = faces[i];

        for (int j = i + 1; j < face_count; j++) {
            if (suppressed[j] > 0) continue;

            //printf("%d, %d, %f\n",i,j,overlap(&faces[i], &faces[j]));
            if (overlap(&faces[i], &faces[j]) > threshold) {
                suppressed[j] = 1;
            }
        }
        if (result_count == 3)break;
    }

    return result_count;
}

