void PrintTensor(struct Uint8Tensor *output, int signed0){
	if(signed0){
		for(int i=0;i<32;i++){
			rt_kprintf("%d,%d\n",i*13+13,(char)output->data_location[i*13+13]);
		}
	}else{
		for(int i=0;i<32;i++){
			rt_kprintf("%d,%d\n",i*13+13,(unsigned char)output->data_location[i*13+13]);
		}
	}
	rt_kprintf("\n");

}

